<script setup lang="ts">
import EditorialHeader from '~/components/molecules/EditorialHeader.vue';
import HealthTrend from '~/components/molecules/HealthTrend.vue';
import HealthCancer from '~/components/molecules/HealthCancer.vue';
import HealthCauses from '~/components/molecules/HealthCauses.vue';
import TopicIllustration from '~/components/atoms/TopicIllustration.vue';
import TopicNavigator from '~/components/organisms/TopicNavigator.vue';
import type { HealthPublication } from '../../shared/health';
import { HEALTH_PUBLICATION_READY } from '~/utils/healthPublication';

if (!import.meta.dev && !HEALTH_PUBLICATION_READY) throw createError({ statusCode: 404, statusMessage: 'Pagina non trovata' });
useHead({ title: 'La salute in Irpinia — IrpiniaConta', meta: HEALTH_PUBLICATION_READY ? [] : [{ name: 'robots', content: 'noindex, nofollow' }] });
useSeoMeta({ description: 'Una fotografia della salute in Irpinia attraverso dati pubblici su prevenzione, malattie e assistenza.' });

const healthSections = [{ id: 'quadro', label: 'Salute nel tempo' }, { id: 'tumori', label: 'Tumori' }, { id: 'malattie', label: 'Cause di morte' }, { id: 'crescita', label: 'Salute mentale e crescita' }, { id: 'assistenza', label: 'La rete di assistenza' }, { id: 'personale', label: 'Il personale sanitario' }, { id: 'metodo', label: 'Metodo e riservatezza' }];
const healthIllustrations: Record<string, string> = { quadro: 'health-overview', tumori: 'health-chemotherapy', malattie: 'health-mortality', crescita: 'health-mental', assistenza: 'topic-health', personale: 'health-staff', metodo: 'health-privacy' };
const { data: publication, error: healthError } = await useFetch<HealthPublication>('/api/health-statistics');
if (healthError.value || !publication.value) throw createError({ statusCode: 503, statusMessage: 'Dati sanitari non disponibili.' });
const health = publication.value;
const healthSeries = health.series;
const number = (value: number) => value.toLocaleString('it-IT', { useGrouping: 'always' });
const decimal = (value: number) => value.toLocaleString('it-IT', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const staffColors = ['#d77851', '#568269', '#a6bdab', '#d2b578', '#7b8790'];
const staffGradient = computed(() => {
  let running = 0;
  const stops = health.staff.roles.map((role, index) => {
    const start = running;
    running += role.value / health.staff.total * 100;
    return `${staffColors[index % staffColors.length]} ${start}% ${running}%`;
  });
  return `conic-gradient(${stops.join(',')})`;
});
const territoryNames = ['Avellino', 'Campania', 'Italia'] as const;
const trends = [
  { code: '01SAL001', title: 'Speranza di vita alla nascita', description: 'Gli anni che un neonato potrebbe vivere se le condizioni di mortalità restassero quelle dell’anno considerato.', unit: 'anni', note: 'Il dato 2024 è provvisorio nella fonte.' },
  { code: '01SAL006', title: 'Mortalità per tumori', description: 'I decessi per tumore tra le persone di 20–64 anni. I valori tengono conto dell’età e permettono di confrontare i territori.', unit: 'decessi standardizzati per 10.000 residenti di 20–64 anni', note: 'Tasso standardizzato per età. Non distingue le sedi tumorali.' },
  { code: '01SAL020', title: 'Mortalità evitabile', description: 'I decessi prima dei 75 anni per cause che, in generale, si possono prevenire o curare.', unit: 'decessi standardizzati per 10.000 residenti di 0–74 anni', note: 'Dal 2020 l’elenco include la mortalità da COVID-19. Un decesso classificato come evitabile non implica che il singolo caso fosse certamente evitabile.' },
  { code: '01SAL007', title: 'Demenze e sistema nervoso', description: 'I decessi per demenze e malattie del sistema nervoso tra le persone dai 65 anni in su.', unit: 'decessi standardizzati per 10.000 residenti di 65 anni e più', note: 'Tasso standardizzato per età. Le cause registrate possono dipendere anche dalla certificazione dei decessi.' },
] as const;
const overviewTrends = trends.filter(trend => trend.code !== '01SAL006' && trend.code !== '01SAL007');
const cancerTrend = trends.find(trend => trend.code === '01SAL006')!;
const mentalTrend = trends.find(trend => trend.code === '01SAL007')!;
const lifeExpectancy2024 = healthSeries['01SAL001']!.Avellino!.find(point => point.year === 2024)!;
const seriesFor = (code: string) => territoryNames.map(name => ({ name: name === 'Avellino' ? 'Provincia di Avellino' : name, points: healthSeries[code]![name]! }));

</script>

<template>
  <div class="supporting-page health-page">
    <TopicNavigator :categories="healthSections" :order="healthSections.map(section => section.id)" :illustrations="healthIllustrations" theme="health" />
    <EditorialHeader eyebrow="Una lettura del territorio" title="La salute" accent="in Irpinia." description="Vivere più a lungo, prevenire, trovare assistenza: uno spazio per comprendere la salute attraverso dati pubblici, con attenzione alle persone dietro i numeri." topic="health">
      <div class="health-hero-stat"><strong>{{ lifeExpectancy2024.value.toLocaleString('it-IT', { minimumFractionDigits: 1 }) }} <small>anni</small></strong><span>Speranza di vita alla nascita<br>Provincia di Avellino · 2024, dato provvisorio<br><a href="https://www.istat.it/notizia/bes-dei-territori-edizione-2025/" target="_blank" rel="noopener noreferrer">Fonte: ISTAT ↗</a></span></div>
      <p class="health-disclaimer">Una pagina sperimentale che rielabora dati pubblici. Per decisioni importanti o usi ufficiali consulta sempre le fonti originali indicate.</p>
      <a href="#tema-quadro">Esplora il quadro <span aria-hidden="true">↓</span></a>
    </EditorialHeader>

    <section id="tema-quadro" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" metric="health-overview" class="health-chapter-art" /><p class="eyebrow">01 / Salute nel tempo</p><h2>Una storia<br><em>fatta di persone.</em></h2></div><p>Due indicatori per conoscere l’Irpinia e confrontarla con Campania e Italia. Ogni dato ha il suo periodo di riferimento.</p></header>
      <HealthTrend v-for="trend in overviewTrends" :key="trend.code" :title="trend.title" :description="trend.description" :unit="trend.unit" :series="seriesFor(trend.code)" :note="trend.note" />
      <p class="health-context"><strong>Leggere i tassi con cura.</strong> I tassi standardizzati consentono confronti che tengono conto della diversa composizione per età: non rappresentano il numero effettivo di persone. Le misure mostrano decessi e non diagnosticano la salute di una comunità.</p>
    </section>
    <section id="tema-tumori" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" metric="health-chemotherapy" class="health-chapter-art" /><p class="eyebrow">02 / Tumori</p><h2>I tumori,<br><em>tra dati e persone.</em></h2></div><p>Due modi per conoscere il fenomeno: i decessi per tumore e le nuove diagnosi registrate nell’ASL.</p></header>
      <HealthTrend :title="cancerTrend.title" :description="cancerTrend.description" :unit="cancerTrend.unit" :series="seriesFor(cancerTrend.code)" :note="cancerTrend.note" />
      <div class="health-subheading"><p class="eyebrow">ASL Avellino · 2020–2022</p><h3>Le nuove diagnosi</h3><p>Il Registro tumori misura i nuovi casi. Le barre mostrano alcune sedi tumorali; il segno scuro indica il margine di incertezza della stima.</p></div>
      <p class="health-context"><strong>Per confrontare i dati.</strong> I valori sono calcolati ogni 100.000 persone e tengono conto dell’età.</p><HealthCancer :groups="health.cancer" />
      <details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Le diagnosi riguardano i residenti nell’ASL Avellino, nel periodo 2020–2022. I tassi usano la popolazione standard europea 2013; gli intervalli sono al 95%.</p><section class="source-citation"><strong>Regione Campania · Registro tumori</strong><a href="https://www.regione.campania.it/sites/default/files/2026-05/asl_avellino_2020-2022_0.pdf" target="_blank" rel="noopener noreferrer">Incidenza oncologica ASL Avellino, pagine 1–2 ↗</a><span>Pubblicato a maggio 2026 · verificato il 3 novembre 2026</span><span>Elaborazione IrpiniaConta · <a href="https://www.regione.campania.it/note-legali">condizioni d’uso della Regione</a>: attribuzione, uso non lucrativo e copyleft, salvo diversa indicazione.</span></section><section class="source-citation"><strong>ISTAT</strong><a href="https://www.istat.it/informazioni-sulla-rilevazione/rilevazione-sulle-cause-di-morte/" target="_blank" rel="noopener noreferrer">Decessi e cause di morte per provincia di residenza ↗</a><span>Dati 2018–2023 · verificati il 3 novembre 2026 · <a href="https://creativecommons.org/licenses/by/4.0/deed.it">CC BY 4.0</a></span></section></details>

    </section>
    <section id="tema-malattie" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" metric="health-mortality" class="health-chapter-art" /><p class="eyebrow">03 / Le cause di morte</p><h2>Le malattie<br><em>nel tempo.</em></h2></div><p>I decessi dei residenti, secondo la causa indicata dall’ISTAT. Questi dati non dicono quante persone vivono con una malattia.</p></header>
      <p class="health-context"><strong>Come leggere i grafici.</strong> Ogni colonna rappresenta un anno. Le scale cambiano da un grafico all’altro: per confrontare le cause, guarda anche i valori. L’età e il numero degli abitanti influenzano i risultati.</p><HealthCauses :causes="health.causes" :codes="['2', '4_1', '5', '6', '7', '8_3']" />
      <details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Fonte: <a href="https://www.istat.it/informazioni-sulla-rilevazione/rilevazione-sulle-cause-di-morte/">ISTAT, Indagine su decessi e cause di morte</a>, dati per provincia di residenza, classificazione europea delle cause, anni 2018–2023, entrambi i sessi. Estrazione SDMX del 3 novembre 2026, dataflow 39_494_DF_DCIS_CMORTE1_RES_1, territorio ITF34. Il gruppo disturbi psichici e comportamentali comprende anche le demenze codificate in questa categoria; non misura la prevalenza dei disturbi mentali. I gruppi selezionati non costituiscono tutte le cause di morte. Elaborazione IrpiniaConta · <a href="https://creativecommons.org/licenses/by/4.0/deed.it">CC BY 4.0</a> salvo diversa indicazione.</p></details>
    </section>
    <section id="tema-crescita" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" metric="health-mental" class="health-chapter-art" /><p class="eyebrow">04 / Salute e prevenzione</p><h2>Salute mentale<br><em>e crescita.</em></h2></div><p>Dati e indagini raccontano aspetti diversi della salute, dalle malattie del sistema nervoso al neurosviluppo.</p></header>
      <HealthTrend :title="mentalTrend.title" :description="mentalTrend.description" :unit="mentalTrend.unit" :series="seriesFor(mentalTrend.code)" :note="mentalTrend.note" />
      <section class="health-neuro" aria-labelledby="neurodevelopment-title">
        <div class="health-neuro__heading"><p class="eyebrow">Neurosviluppo · provincia di Avellino</p><h3 id="neurodevelopment-title">Le persone nello spettro autistico</h3></div>
        <div class="health-neuro__content"><strong class="health-neuro__number">{{ number(health.autism.value) }}</strong><div><p>È il numero di persone nello spettro autistico in provincia citato dalla direttrice dell’ASL in un comunicato della Regione del 15 dicembre 2025.</p><p class="health-neuro__note">Un primo dato per conoscere il territorio, che richiede ulteriori approfondimenti su criteri, periodo e persone considerate. Non rappresenta necessariamente il totale dei residenti autistici e non permette confronti nel tempo.</p></div></div>
        <details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Il valore è una dichiarazione istituzionale, non una serie epidemiologica. La data di pubblicazione non coincide necessariamente con la data di rilevazione. Non sono specificati metodo, fascia d’età, copertura o criteri di conteggio. Serve una verifica con l’ASL prima di interpretarlo come dato sanitario strutturato.</p><section class="source-citation"><strong>Regione Campania · dichiarazione della direttrice ASL Avellino</strong><a href="https://www.regione.campania.it/comunicazione/area-stampa/comunicati/15122025-comunicato-n-193-completamento-lavori-centro-l-autismo-valle-ad-avellino" target="_blank" rel="noopener noreferrer">Comunicato sul Centro per l’autismo · 15 dicembre 2025 ↗</a><span>Comunicato aggiornato il 18 dicembre 2025 · verificato il 3 novembre 2026</span><span><a href="https://www.regione.campania.it/note-legali" target="_blank" rel="noopener noreferrer">Condizioni d’uso della Regione</a>: citazione della fonte, uso non lucrativo e copyleft, salvo diversa indicazione.</span></section></details>
      </section>

      <div class="survey-grid">
      <article class="survey-card"><p class="eyebrow">PASSI · ASL Avellino · 2008–2011</p><h3>Sintomi depressivi riferiti</h3><p>Una stima campionaria storica negli adulti di 18–69 anni, ottenuta con un questionario: non equivale a una diagnosi di depressione né descrive la situazione attuale.</p><div class="survey-number"><strong>{{ decimal(health.survey.value) }}%</strong><span>degli intervistati<br>con sintomi rilevati</span></div><div class="survey-interval"><span>Intervallo di confidenza al 95%</span><strong>{{ decimal(health.survey.low) }}% – {{ decimal(health.survey.high) }}%</strong></div><p class="survey-note">Il rapporto non specifica il numero di risposte valide per questa stima. L’ASL elenca anche un rapporto 2013–2016: non lo abbiamo ancora potuto verificare direttamente.</p><a href="https://www.epicentro.iss.it/passi/pdf2013/Passi%20ASL%20Avellino%202008-2011.pdf">Rapporto PASSI, pp. 19–20 ↗</a><small>Rilevazione 2008–2011 · non attuale · riuso da verificare</small></article></div>
    </section>
    <section id="tema-assistenza" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" class="health-chapter-art" /><p class="eyebrow">05 / La rete di assistenza</p><h2>Lo spazio<br><em>per curare.</em></h2></div><p>La dotazione ospedaliera racconta una parte dell’offerta, non la disponibilità effettiva, i tempi d’attesa o la qualità delle cure.</p></header>
      <div class="health-feature"><div class="health-feature__number"><span>Strutture nella provincia · 1 gennaio 2023</span><strong>{{ number(health.beds.total) }}</strong><span>posti letto rilevati complessivamente</span><small>Pubbliche ed equiparate e attività accreditata delle case di cura private.</small></div><div class="health-chart"><h3>Per tipo di assistenza</h3><p>Posti letto rilevati · provincia di Avellino</p><ul><li v-for="bed in health.beds.byType" :key="bed.name"><div><span>{{ bed.name }}</span><strong>{{ number(bed.value) }}</strong></div><div class="health-track" aria-hidden="true"><span class="is-primary" :style="{width: `${bed.value / health.beds.total * 100}%`}" /></div></li></ul><p class="health-chart__note">Scala da 0 a {{ number(health.beds.total) }} posti; include degenza ordinaria, a pagamento, day hospital e day surgery.</p></div></div><div class="health-breakdown"><div><h3>Come si ricovera</h3><p>Ripartizione dei posti per regime</p><ul><li v-for="item in health.beds.byRegime" :key="item.name"><span>{{ item.name }}</span><strong>{{ number(item.value) }}</strong></li></ul></div><div><h3>Dove si trova l’offerta</h3><p>Posti per tipologia di struttura</p><ul><li v-for="item in health.beds.byProvider" :key="item.name"><span>{{ item.name }}</span><strong>{{ number(item.value) }}</strong></li></ul></div></div><details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Fonte: <a href="https://www.dati.salute.gov.it/it/dataset/posti-letto-struttura-ospedaliera-2023/">Ministero della Salute, posti letto per struttura ospedaliera 2023</a>. Somma delle righe riferite alla provincia di Avellino per disciplina; aggiornamento del dataset 29 luglio 2025. Elaborazione IrpiniaConta · <a href="https://www.dati.gov.it/iodl/2.0/">IODL 2.0</a> · verificato il 3 novembre 2026.</p></details>    <section class="health-hospital" aria-labelledby="health-hospital-title"><p class="eyebrow">Assistenza ospedaliera · 2021</p><h3 id="health-hospital-title">I ricoveri nelle strutture del territorio</h3><div class="health-hospital__body"><strong>{{ number(health.admissions.total) }}</strong><div><p>ricoveri registrati complessivamente nelle attività attribuite all’ASL Avellino e all’azienda ospedaliera Moscati.</p><p>È un dato storico: comprende anche strutture private accreditate e ospedali classificati attribuiti all’ASL. Conta i ricoveri, non le persone; include anche pazienti residenti altrove.</p></div></div><details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Somma dei totali delle righe ASL Avellino e A.O. Moscati nella tabella regionale SDO 2021. Include ricoveri per acuti, riabilitazione e lungodegenza; il dato risale al periodo della pandemia. Non rappresenta i ricoveri dei soli residenti né i pazienti distinti.</p><section class="source-citation"><strong>Regione Campania · dati SDO 2021</strong><a href="https://burc.regione.campania.it/eBurcWeb/directServlet?ATTACH_ID=214540&amp;DOCUMENT_ID=00141867" target="_blank" rel="noopener noreferrer">Documento programmatico, ricoveri per azienda, p. 232 ↗</a><span>Anno dei dati 2021 · documento 2023 · verificato il 3 novembre 2026</span><span>Elaborazione IrpiniaConta · condizioni di riuso da verificare.</span></section></details></section>
</section>
    <section id="tema-personale" class="health-section"><header class="health-heading"><div><TopicIllustration topic="health" metric="health-staff" class="health-chapter-art" /><p class="eyebrow">06 / Le persone che curano</p><h2>Il lavoro<br><em>della sanità pubblica.</em></h2></div><p>Una fotografia dei dipendenti a tempo indeterminato delle due aziende pubbliche considerate: ASL Avellino e Azienda ospedaliera San Giuseppe Moscati.</p></header>
      <div class="staff-card"><div class="staff-donut" role="img" :style="{background: staffGradient}" :aria-label="`Personale per ruolo: ${health.staff.roles.map(role => `${role.name} ${number(role.value)}`).join(', ')}.`"><span><strong>{{ number(health.staff.total) }}</strong><small>dipendenti<br>in totale</small></span></div><div class="staff-content"><h3>Le professioni, insieme</h3><p>Personale in servizio al 31 dicembre 2022</p><ul><li v-for="(role, index) in health.staff.roles" :key="role.name"><i :style="{background:staffColors[index % staffColors.length]}"/><span>{{ role.name }}</span><strong>{{ number(role.value) }}</strong></li></ul><p>Nel ruolo sanitario sono compresi <strong>{{ number(health.staff.physicians) }} medici e odontoiatri</strong> e <strong>{{ number(health.staff.nurses) }} infermieri</strong>: sono sottoinsiemi, non si sommano al totale.</p></div></div>
      <details class="story-source health-source"><summary>Significato e fonti del dato</summary><p>Fonte: <a href="https://www.dati.salute.gov.it/it/dataset/personale-dipendente-delle-asl-aziende-ospedaliere-aziende-ospedaliere-universitarie-e-2/">Ministero della Salute, Conto annuale T1 2022</a>, aziende 201 e 905; aggiornato il 12 giugno 2026. Somma dei ruoli e dei dipendenti delle due aziende, con personale dirigente come descritto nel file. Sono esclusi altre aziende, personale privato, convenzionato e rapporti non ricompresi nel dataset: non è il totale di tutti i professionisti del territorio. Elaborazione IrpiniaConta · <a href="https://www.dati.gov.it/iodl/2.0/">IODL 2.0</a> · verifica 3 novembre 2026.</p></details></section>
    <section id="tema-metodo" class="health-method"><div><TopicIllustration topic="health" metric="health-privacy" class="health-chapter-art" /><p class="eyebrow">Metodo e tutela</p><h2>La riservatezza<br>viene prima del dettaglio.</h2></div><div><p>Mostriamo dati sulla provincia o sull’intera ASL, mai su singole persone, comuni o distretti.</p><p>Prima di pubblicare, controlliamo che numeri piccoli e incroci non permettano di riconoscere le persone.</p><p>Le indagini su campioni sono stime. Accanto ai dati trovi il periodo, la fonte e le informazioni per interpretarli.</p></div></section>
  </div>
</template>

